INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 15, 'theory', 'Quiz: Mini-8 assembler');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 15, 0, 'What is register r0 always equal to in Mini-8?', '["The last result", "The program counter", "The disk address", "Zero, whatever is written to it"]', 3, 'A constant zero is handy: it is needed for comparisons with zero and for copying (mv) without separate instructions.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 15, 1, 'How do you write the byte from r1 to the address in r2?', '["lb r1, 0(r2)", "sb r1, 0(r2)", "li r1, r2", "add r1, r2, r0"]', 1, 'sb is store byte: memory[r2 + 0] = r1. lb does the opposite, reading a byte from memory into a register.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 15, 2, 'What does the assembler turn inc r1 into?', '["addi r1, r1, 1", "A separate inc instruction", "sub r1, r1, r0", "hlt"]', 0, 'inc is a pseudo-instruction: a shorthand that the assembler replaces with the real instruction addi.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 15, 3, 'How do you detect the end in a loop over a string?', '["By the number of passes", "By register r0", "By the zero byte: bnez/beqz on the value read", "By the hlt instruction"]', 2, 'Strings in memory end with a 0 byte. Once it has been read, the loop exits.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 15, 4, 'How do you detect a carry when adding the low bytes of two numbers?', '["By the C flag, Mini-8 has one", "By comparison: if the sum is less than one of the addends, there was a carry", "Through r0", "A carry never occurs"]', 1, 'Mini-8 has no carry flag. A result smaller than an addend when adding modulo 256 means overflow; bltu is used.');
